  -moz-box-sizing: border-box;
  -webkit-box-sizing: border-box;
  box-sizing: border-box;
  background-repeat: no-repeat;
  padding: 0;
  margin: 0;
}

.mhForm {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans', sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji';
  font-size: 14px;
}

/* Form elements */

.mhForm__button {
  padding: 11px 20px;
  font-size: 14px;
  font-weight: 400;
  background-color: #3E52FF;
  color: #fff;
  border: none;
  border-radius: 5px;
  cursor: pointer;
}

.mhForm__button:hover {
  background-color: #2e41e7;
}

.mhForm__checkboxLabel,
.mhForm__radioLabel {
  display: inline-block;
  margin-left: 10px;
  line-height: 19px;
}

.mhForm__control {
  margin-bottom: 20px;
}

.mhForm__control--checkboxes {
  border: 0;
}

.mhForm__input {
  border-radius: 2px;
  border: 1px solid #e0e3e5;
}

.mhForm__input--checkbox,
.mhForm__input--radio {
  flex: 0 0 auto;
}

.mhForm__input--email,
.mhForm__input--number,
.mhForm__input--text,
.mhForm__select {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  background-color: #fff;
  border-color: #e0e3e5;
  border-width: 1px;
  border-radius: 3px;
  padding: 8px 12px;
  font-size: 14px;
  line-height: 20px;
  width: 100%;
}

.mhForm__label {
  color: #001235;
  display: flex;
  font-weight: 400;
  margin-bottom: 3px;
}

.mhForm__label--checkbox {
  align-items: center;
}

.mhForm__select {
  background: #fff url("data:image/svg+xml;charset=utf-8,%3C?xml version='1.0' encoding='utf-8'?%3E %3Csvg version='1.1' xmlns='http://www.w3.org/2000/svg' xmlns:xlink='http://www.w3.org/1999/xlink' height='62.5' width='116.9' fill='%238A919A'%3E %3Cpath d='M115.3,1.6 C113.7,0 111.1,0 109.5,1.6 L58.5,52.7 L7.4,1.6 C5.8,0 3.2,0 1.6,1.6 C0,3.2 0,5.8 1.6,7.4 L55.5,61.3 C56.3,62.1 57.3,62.5 58.4,62.5 C59.4,62.5 60.5,62.1 61.3,61.3 L115.2,7.4 C116.9,5.8 116.9,3.2 115.3,1.6Z'/%3E %3C/svg%3E") calc(100% - 12px) 50% / 12px no-repeat;
  padding-right: 35px;
  color: inherit;
  background-color: #fff;
  font-family: inherit;
  font-size: inherit;
  padding: 10px;
}

.mhForm__select::-ms-expand {
  display: none;
}

/* Validation */

.mhForm__validationError {
  margin-top: 5px;
  color: #AE3523;
}

/* Success and error */

.mhForm__error {
  background-color: #F9E9E7;
  color: #AE3523;
  margin-bottom: 20px;
}

.mhForm__success,
.mhForm__error {
  padding: 20px;
}

.mhForm__success {
  background-color: #E4F3F0;
  color: #2F9782;
}

.mhForm__success ~ * {
  display: none;
}

.mhForm__dateInput {
  -moz-appearance: textfield
}

.mhForm__dateInput::-webkit-inner-spin-button {
  -webkit-appearance: none;
}

.mhForm__dateInputWrapper {
  display: flex;
  grid-gap: 10px;
}

.mhForm__partialDate {
  width: 75px;
}

.mhForm__partialDate--year {
  width: 85px;
